<template><section class="page"><div class="page-title"><div><h1>系统设置</h1><p class="muted">时间、存储、服务和日志策略</p></div></div><div class="cards"><article><h2>时间与区域</h2><label>时区<select v-model="time.timezone"><option>UTC</option><option>Asia/Shanghai</option></select></label><label>NTP 开关<input type="checkbox" v-model="time.ntp_enabled"></label><label>NTP 服务器<input v-model="time.ntp_server"></label><button @click="save('/api/time',time)">保存时间设置</button></article><article><h2>存储策略</h2><label>自动清理天数<input type="number" v-model.number="storage.auto_cleanup_days"></label><label>保留视频<input type="checkbox" v-model="storage.video_retention_enabled"></label><label>低空间阈值 %<input type="number" v-model.number="storage.low_space_threshold_percent"></label><button @click="save('/api/storage-policy',storage)">保存存储策略</button></article><article><h2>服务配置</h2><label>API 端口<input type="number" v-model.number="services.api_port"></label><label>Node-RED 端口<input type="number" v-model.number="services.node_red_port"></label><button @click="save('/api/services/config',services)">保存服务配置</button><p class="hint">修改端口需要管理员权限。</p></article><article><h2>日志设置</h2><label>日志级别<select v-model="logs.level"><option>INFO</option><option>WARNING</option><option>ERROR</option></select></label><label>保存天数<input type="number" v-model.number="logs.days"></label><p class="hint">日志清理请在设备管理页面执行。</p></article></div><p class="hint">{{message}}</p></section></template><script setup>import {ref,onMounted} from 'vue';import {request,put} from '../api';const time=ref({}),storage=ref({}),services=ref({}),logs=ref({level:'INFO',days:30}),message=ref('');onMounted(async()=>{[time.value,storage.value,services.value]=await Promise.all([request('/api/time'),request('/api/storage-policy'),request('/api/services/config')])});const save=async(path,data)=>{try{await put(path,data);message.value='设置已保存'}catch(e){message.value=e.message}}</script>
